<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require_once __DIR__.'/../Config/Database.php';$db=(new Database())->connect();$cols=$db->query('SHOW COLUMNS FROM compras')->fetchAll(PDO::FETCH_COLUMN);
